    private final String code = "*-----------------------------------------------------------------------------\n* <Rating>1113</Rating>\n*-----------------------------------------------------------------------------\n* Version 9 15/11/00  GLOBUS Release No. G11.1.01 11/12/00\n    SUBROUTINE \n*\n****************************************************************************\n*  Developed By     : \n*  Developed For    : \n*  Developed Date   : \n*\n******************************************************************\n* This Application is use to perform these actions\n*\n*\n*\n*\n*\n*\n******************************************************************\n*\n*\n    $INSERT I_COMMON\n    $INSERT I_EQUATE\n\n*\n*************************************************************************\n\n    GOSUB DEFINE.PARAMETERS\n\n    IF LEN(V$FUNCTION) GT 1 THEN\n        GOTO V$EXIT\n    END\n\n    CALL MATRIX.UPDATE\n\n    GOSUB INITIALISE          ;* Special Initialising\n\n*************************************************************************\n\n* Main Program Loop\n    LOOP\n\n        CALL RECORDID.INPUT\n\n    UNTIL (MESSAGE EQ 'RET')\n\n        V$ERROR = ''\n\n        IF MESSAGE EQ 'NEW FUNCTION' THEN\n\n            GOSUB CHECK.FUNCTION        ;* Special Editing of Function\n\n            IF V$FUNCTION EQ 'E' OR V$FUNCTION EQ 'L' THEN\n                CALL FUNCTION.DISPLAY\n                V$FUNCTION = ''\n            END\n\n        END ELSE\n\n            GOSUB CHECK.ID    ;* Special Editing of ID\n            IF V$ERROR THEN GOTO MAIN.REPEAT\n\n            CALL RECORD.READ\n\n            IF MESSAGE EQ 'REPEAT' THEN\n                GOTO MAIN.REPEAT\n            END\n\n            CALL MATRIX.ALTER\n\n            GOSUB CHECK.RECORD          ;* Special Editing of Record\n            IF V$ERROR THEN GOTO MAIN.REPEAT\n            LOOP\n                GOSUB PROCESS.FIELDS    ;* ) For Input\n                GOSUB PROCESS.MESSAGE   ;* ) Applications\n            WHILE (MESSAGE EQ 'ERROR') REPEAT\n\n        END\n\nMAIN.REPEAT:\n    REPEAT\n\n    V$EXIT:\n    RETURN          ;* From main program\n\n*************************************************************************\n*                      S u b r o u t i n e s                            *\n*************************************************************************\n\nPROCESS.FIELDS:\n\n* Input or display the record fields.\n\n    LOOP\n        IF SCREEN.MODE EQ 'MULTI' THEN\n            IF FILE.TYPE EQ 'I' THEN\n                CALL FIELD.MULTI.INPUT\n            END ELSE\n                CALL FIELD.MULTI.DISPLAY\n            END\n        END ELSE\n            IF FILE.TYPE EQ 'I' THEN\n                CALL FIELD.INPUT\n            END ELSE\n                CALL FIELD.DISPLAY\n            END\n        END\n\n    WHILE NOT(MESSAGE)\n\n        GOSUB CHECK.FIELDS    ;* Special Field Editing\n\n        IF T.SEQU NE '' THEN T.SEQU<-1> = A + 1\n\n    REPEAT\n\n    RETURN\n\n*************************************************************************\n\nPROCESS.MESSAGE:\n\n* Processing after exiting from field input (PF5)\n\n    IF MESSAGE = 'DEFAULT' THEN\n        MESSAGE = 'ERROR'     ;* Force the processing back\n        IF V$FUNCTION <> 'D' AND V$FUNCTION <> 'R' THEN\n            GOSUB CROSS.VALIDATION\n        END\n    END\n\n    IF MESSAGE = 'PREVIEW' THEN\n        MESSAGE = 'ERROR'     ;* Force the processing back\n        IF V$FUNCTION <> 'D' AND V$FUNCTION <> 'R' THEN\n            GOSUB CROSS.VALIDATION\n            IF NOT(V$ERROR) THEN\nREM >               GOSUB DELIVERY.PREVIEW   ; * Activate print preview\n            END\n        END\n    END\n\n    IF MESSAGE EQ 'VAL' THEN\n        MESSAGE = ''\n        BEGIN CASE\n        CASE V$FUNCTION EQ 'D'\n            GOSUB CHECK.DELETE          ;* Special Deletion checks\n        CASE V$FUNCTION EQ 'R'\n            GOSUB CHECK.REVERSAL        ;* Special Reversal checks\n        CASE OTHERWISE\n            GOSUB CROSS.VALIDATION      ;* Special Cross Validation\n            IF NOT(V$ERROR) THEN\n                GOSUB OVERRIDES\n            END\n        END CASE\n        IF NOT(V$ERROR) THEN\n            GOSUB BEFORE.UNAU.WRITE     ;* Special Processing before write\n        END\n        IF NOT(V$ERROR) THEN\n            CALL UNAUTH.RECORD.WRITE\n            IF MESSAGE NE \"ERROR\" THEN\n                GOSUB AFTER.UNAU.WRITE  ;* Special Processing after write\n            END\n        END\n\n    END\n\n    IF MESSAGE EQ 'AUT' THEN\n        GOSUB AUTH.CROSS.VALIDATION     ;* Special Cross Validation\n        IF NOT(V$ERROR) THEN\n            GOSUB BEFORE.AUTH.WRITE     ;* Special Processing before write\n        END\n\n        IF NOT(V$ERROR) THEN\n\n            CALL AUTH.RECORD.WRITE\n\n            IF MESSAGE NE \"ERROR\" THEN\n                GOSUB AFTER.AUTH.WRITE  ;* Special Processing after write\n            END\n        END\n\n    END\n\n    RETURN\n\n*************************************************************************\n*                      Special Tailored Subroutines                     *\n*************************************************************************\n\nCHECK.ID:\n* Validation and changes of the ID entered.  Set ERROR to 1 if in error.\n*\n\n*\n\n*\n    RETURN\n*\n*************************************************************************\n\nCHECK.RECORD:\n\n* Validation and changes of the Record.  Set ERROR to 1 if in error.\n\n*\n    IF ETEXT THEN V$ERROR = 1\n\n    RETURN\n\n*************************************************************************\n\nCHECK.FIELDS:\n*\n**\n*\n\n*\n\n    RETURN\n*\n*************************************************************************\n\nCROSS.VALIDATION:\n\n*\n    V$ERROR = ''\n    ETEXT = ''\n    TEXT = ''\n*\nREM > CALL XX.CROSSVAL\n*\n* If END.ERROR has been set then a cross validation error has occurred\n*\n    IF END.ERROR THEN\n        A = 1\n        LOOP UNTIL T.ETEXT<A> <> \"\" DO A = A+1 ; REPEAT\n        T.SEQU = A\n        V$ERROR = 1\n        MESSAGE = 'ERROR'\n    END\n    RETURN          ;* Back to field input via UNAUTH.RECORD.WRITE\n\n*************************************************************************\n\nOVERRIDES:\n*\n*  Overrides should reside here.\n*\n    V$ERROR = ''\n    ETEXT = ''\n    TEXT = ''\nREM > CALL XX.OVERRIDE\n*\n\n*\n    IF TEXT = \"NO\" THEN       ;* Said NO to override\n        V$ERROR = 1\n        MESSAGE = \"ERROR\"     ;* Back to field input\n\n    END\n    RETURN\n\n*************************************************************************\n\nAUTH.CROSS.VALIDATION:\n\n\n    RETURN\n\n*************************************************************************\n\nCHECK.DELETE:\n\n\n    RETURN\n\n*************************************************************************\n\nCHECK.REVERSAL:\n\n\n    RETURN\n\n*************************************************************************\nDELIVERY.PREVIEW:\n\n    RETURN\n\n*************************************************************************\n\nBEFORE.UNAU.WRITE:\n*\n*  Contract processing code should reside here.\n*\nREM > CALL XX.         ;* Accounting, Schedule processing etc etc\n*\n*\n    IF TEXT = \"NO\" THEN       ;* Said No to override\n        CALL TRANSACTION.ABORT          ;* Cancel current transaction\n        CALL ERR\n        V$ERROR = 1\n        MESSAGE = \"ERROR\"     ;* Back to field input\n        RETURN\n    END\n\n*\n* Additional updates should be performed here\n*\nREM > CALL XX...\n\n\n\n    RETURN\n\n*************************************************************************\n\nAFTER.UNAU.WRITE:\n\n\n    RETURN\n\n*************************************************************************\n\nAFTER.AUTH.WRITE:\n*\n*\n    RETURN\n\n*************************************************************************\n\nBEFORE.AUTH.WRITE:\n*\n*-----------------------------------\n*\n** Update Each Certificate information\n*\n\n\n*-----------------------------------------------\n    IF E THEN\n        TEXT = \"NO\"\n    END\n*\n    BEGIN CASE\n    CASE R.NEW(V-8)[1,3] = \"INA\"        ;* Record status\nREM > CALL XX.AUTHORISATION\n    CASE R.NEW(V-8)[1,3] = \"RNA\"        ;* Record status\nREM > CALL XX.REVERSAL\n\n    END CASE\n\n    RETURN\n\n*************************************************************************\n\nCHECK.FUNCTION:\n\n* Validation of function entered.  Set FUNCTION to null if in error.\n\n    IF INDEX('VRCH',V$FUNCTION,1) THEN\n        E = 'FUNCTION NOT ALLOWED FOR THIS APPLICATION'\n        CALL ERR\n        V$FUNCTION = ''\n    END\n\n    RETURN\n\n*************************************************************************\n\nINITIALISE:\n*\n** Initialie File(s)\n*\n\n*\n** Init. few Common Vars\n*\n*\n    RETURN\n*\n*************************************************************************\n\nDEFINE.PARAMETERS:  * SEE 'I_RULES' FOR DESCRIPTIONS *\n\nREM > CALL XX.FIELD.DEFINITIONS\n*\n    MAT F = \"\" ; MAT N = \"\" ; MAT T = \"\"\n    MAT CONCATFILE = \"\" ; MAT CHECKFILE = \"\"\n**\n    ID.F = \"ID\" ; ID.N = \"35\" ; ID.T = \"A\"\n*\n    Z = 0\n*\n\n    Z += 1 ; F(Z) = \"ANY_TEXT\"           ; N(Z)= '6'   ; T(Z)= 'A'\n    Z += 1 ; F(Z) = \"DROPDOWN\"   ; N(Z) = \"7\"     ; T(Z)= 'A'\n    Z += 1 ; F(Z) = \"XX.LOCAL.REF\"   ; N(Z) = \"35\"     ; T(Z) = \"A\";\n    Z += 1 ; F(Z) = \"DATE\"   ; N(Z) = \"35\"     ; T(Z) = \"D\";\n    Z += 1 ; F(Z) = \"AMOUNT\"   ; N(Z) = \"35\"     ; T(Z) = \"AMT\";\n    Z += 1 ; F(Z) = \"ANY.CHARACTER\"   ; N(Z) = \"35\"     ; T(Z) = \"ANY\";\n    Z += 1 ; F(Z) = \"XX.MULTI.VALUE\"   ; N(Z) = \"35\"     ; T(Z) = \"A\";\n    Z += 1 ; F(Z) = \"XX<.GROUP.START\"   ; N(Z) = \"35\"     ; T(Z) = \"A\";\n    Z += 1 ; F(Z) = \"XX-.GROUP.FILEDS\"   ; N(Z) = \"35\"     ; T(Z) = \"A\";\n    Z += 1 ; F(Z) = \"XX-.GROUP.FILEDS\"   ; N(Z) = \"35\"     ; T(Z) = \"A\";\n    Z += 1 ; F(Z) = \"XX>.GROUP.END\"   ; N(Z) = \"35\"     ; T(Z) = \"A\";\n\n\n    Z+=1 ; F(Z) = \"RESERVED.10\"               ; N(Z)=\"35\"     ; T(Z) =\"A\"  ; T(Z)<3> = \"NOINPUT\"\n    Z+=1 ; F(Z) = \"RESERVED.09\"               ; N(Z)=\"35\"     ; T(Z) =\"A\"  ; T(Z)<3> = \"NOINPUT\"\n    Z+=1 ; F(Z) = \"RESERVED.08\"               ; N(Z)=\"35\"     ; T(Z) =\"A\"  ; T(Z)<3> = \"NOINPUT\"\n    Z+=1 ; F(Z) = \"RESERVED.07\"               ; N(Z)=\"35\"     ; T(Z) =\"A\"  ; T(Z)<3> = \"NOINPUT\"\n    Z+=1 ; F(Z) = \"RESERVED.06\"               ; N(Z)=\"35\"     ; T(Z) =\"A\"  ; T(Z)<3> = \"NOINPUT\"\n    Z+=1 ; F(Z) = \"RESERVED.05\"               ; N(Z)=\"35\"     ; T(Z) =\"A\"  ; T(Z)<3> = \"NOINPUT\"\n    Z+=1 ; F(Z) = \"RESERVED.04\"               ; N(Z)=\"35\"     ; T(Z) =\"A\"  ; T(Z)<3> = \"NOINPUT\"\n    Z+=1 ; F(Z) = \"RESERVED.03\"               ; N(Z)=\"35\"     ; T(Z) =\"A\"  ; T(Z)<3> = \"NOINPUT\"\n    Z+=1 ; F(Z) = \"RESERVED.02\"               ; N(Z)=\"35\"     ; T(Z) =\"A\"  ; T(Z)<3> = \"NOINPUT\"\n    Z+=1 ; F(Z) = \"RESERVED.01\"               ; N(Z)=\"35\"     ; T(Z) =\"A\"  ; T(Z)<3> = \"NOINPUT\"\n\n    V = Z + 9\n\n    PREFIX = \"\"\n    RETURN\n*\n*************************************************************************\n\n\n***********************  This is the Final End  ***********************\n*\n*\nEND";
